// Reuses a PNG already generated by the root agent. No provider requests are
// allowed here; only the local ONNX cutout and intercepted UI replay run.
import { chromium } from 'playwright';
import assert from 'node:assert/strict';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

const args = process.argv.slice(2);
const option = (name, fallback) => {
  const index = args.indexOf(name);
  if (index < 0) return fallback;
  if (!args[index + 1] || args[index + 1].startsWith('--')) throw new Error(`${name} requires a value`);
  return args[index + 1];
};
const base = option('--url', process.env.SMOKE_URL || 'http://127.0.0.1:4173/wardrobe/');
const output = path.resolve(option('--output', 'artifacts/flatlay-live'));
const generatedPath = path.resolve(option('--generated', path.join(output, 'generated-flatlay.png')));
const originalPath = path.resolve(option('--original', path.join(output, 'original-photo.jpg')));
const category = option('--category', '上装');
const description = option('--description', '');
const model = option('--model', 'reused-real-result');
const replayBase = 'https://reused-flatlay.invalid';
assert.ok(['上装', '下装', '连衣裙', '外套', '鞋履', '配饰'].includes(category), 'Unknown garment category');
const generatedBytes = await readFile(generatedPath).catch(error => {
  if (error.code === 'ENOENT') throw new Error(`The root agent has not saved ${generatedPath} yet. Run this script after visual review of that generated image.`);
  throw error;
});
assert.ok(generatedBytes.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10])), 'Generated fixture must be PNG');
const generated = `data:image/png;base64,${generatedBytes.toString('base64')}`;
const originalBytes = await readFile(originalPath).catch(error => { if (error.code === 'ENOENT') return null; throw error; });
const originalMime = originalBytes?.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10])) ? 'image/png' : 'image/jpeg';
const original = originalBytes ? `data:${originalMime};base64,${originalBytes.toString('base64')}` : null;
await mkdir(output, { recursive: true });
const browser = await chromium.launch({ channel: 'chrome', headless: true });
const context = await browser.newContext({ viewport: { width: 1440, height: 1050 } });
const page = await context.newPage();
const resources = [], forbiddenRequests = [], errors = [], replayRequests = [], progress = [];
const checks = [];
let cutout, alpha, ui = { skipped: true, reason: 'Original live request photograph was not provided.' };
const action = name => page.locator(`[data-action="${name}"]`).filter({ visible: true }).first();
page.on('pageerror', error => errors.push(error.message));
page.on('response', response => {
  if (/\.(onnx|wasm)(?:\?|$)/.test(response.url())) resources.push({ url: response.url(), status: response.status() });
});
await context.route('**/*', async route => {
  const request = route.request(), url = new URL(request.url());
  if (url.origin === new URL(base).origin) { await route.continue(); return; }
  if (url.origin !== replayBase) {
    forbiddenRequests.push({ method: request.method(), url: request.url() });
    await route.abort('blockedbyclient'); return;
  }
  const headers = {
    'Access-Control-Allow-Origin': new URL(base).origin,
    'Access-Control-Allow-Headers': 'Content-Type, X-Closet-Token',
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
    'Content-Type': 'application/json',
  };
  if (request.method() === 'OPTIONS') { await route.fulfill({ status: 204, headers }); return; }
  assert.equal(url.pathname, '/api/flatlay'); assert.equal(request.method(), 'POST');
  replayRequests.push(request.postDataJSON());
  await route.fulfill({ status: 200, headers, body: JSON.stringify({ image: generated, kind: 'flatlay', provider: 'dashscope', model }) });
});

async function check(name, run) {
  const started = performance.now();
  try { await run(); checks.push({ name, passed: true, milliseconds: Math.round(performance.now() - started) }); console.log(`PASS ${name}`); }
  catch (error) { checks.push({ name, passed: false, error: error.stack }); throw error; }
}

try {
  await page.goto(base, { waitUntil: 'networkidle' });
  await page.locator('#garment-results .garment-card').first().waitFor();
  await check('real browser ONNX inference removes the generated white background and preserves foreground pixels', async () => {
    const result = await page.evaluate(async source => {
      const progress = [];
      const image = await (await import('./src/cutout.js')).removeBackground(source, { onProgress: value => progress.push(value) });
      return { image, progress };
    }, generated);
    cutout = result.image; progress.push(...result.progress);
    alpha = await page.evaluate(async images => {
      const inspect = async source => {
        const image = new Image(); image.src = source; await image.decode();
        const canvas = document.createElement('canvas'); canvas.width = image.naturalWidth; canvas.height = image.naturalHeight;
        const drawing = canvas.getContext('2d', { willReadFrequently: true }); drawing.drawImage(image, 0, 0);
        const data = drawing.getImageData(0, 0, canvas.width, canvas.height).data;
        let transparent = 0, opaque = 0, soft = 0, whiteOpaque = 0, edgePixels = 0, transparentEdge = 0;
        for (let y = 0; y < canvas.height; y++) for (let x = 0; x < canvas.width; x++) {
          const offset = (y * canvas.width + x) * 4, a = data[offset + 3];
          if (a < 8) transparent++; else if (a > 247) opaque++; else soft++;
          if (a > 247 && data[offset] > 175 && data[offset + 1] > 175 && data[offset + 2] > 175) whiteOpaque++;
          if (x === 0 || y === 0 || x === canvas.width - 1 || y === canvas.height - 1) { edgePixels++; if (a < 8) transparentEdge++; }
        }
        const pixels = canvas.width * canvas.height;
        return { width: canvas.width, height: canvas.height, pixels, transparent, opaque, soft, whiteOpaque, transparentFraction: transparent / pixels, opaqueFraction: opaque / pixels, transparentEdgeFraction: transparentEdge / edgePixels };
      };
      return { generated: await inspect(images.generated), final: await inspect(images.cutout) };
    }, { generated, cutout });
    assert.notEqual(cutout, generated);
    assert.ok(alpha.final.transparentFraction > 0.05, `No useful transparent background: ${JSON.stringify(alpha.final)}`);
    assert.ok(alpha.final.opaqueFraction > 0.01, `No preserved clothing foreground: ${JSON.stringify(alpha.final)}`);
    assert.ok(alpha.final.transparentEdgeFraction > 0.95, 'Cutout border should be transparent');
    assert.ok(resources.some(resource => resource.url.includes('.onnx') && resource.status === 200), 'Actual ONNX weights were not fetched');
    assert.ok(resources.some(resource => resource.url.includes('.wasm') && resource.status === 200), 'Actual WASM runtime was not fetched');
    assert.ok(progress.some(value => value.stage === 'infer') && progress.some(value => value.stage === 'done'));
    await writeFile(path.join(output, 'final-transparent-flatlay.png'), Buffer.from(cutout.split(',')[1], 'base64'));
    await writeFile(path.join(output, 'alpha-stats.json'), JSON.stringify(alpha, null, 2));
  });

  await check('save an original / generated / transparent comparison artifact', async () => {
    const comparison = await page.evaluate(async images => {
      const panels = [
        ...(images.original ? [{ image: images.original, title: 'Original live request photograph', checker: false }] : []),
        { image: images.generated, title: 'Real DashScope generation (reused)', checker: false },
        { image: images.cutout, title: 'Actual local ONNX transparent PNG', checker: true },
      ];
      const width = 440, height = 550;
      const canvas = document.createElement('canvas'); canvas.width = width * panels.length; canvas.height = height;
      const drawing = canvas.getContext('2d'); drawing.fillStyle = '#fafaf7'; drawing.fillRect(0, 0, canvas.width, canvas.height);
      drawing.font = '18px Arial'; drawing.textAlign = 'center';
      for (let index = 0; index < panels.length; index++) {
        const panel = panels[index], left = width * index + 20, top = 66, boxWidth = width - 40, boxHeight = height - 112;
        drawing.fillStyle = '#263c32'; drawing.fillText(panel.title, width * index + width / 2, 34);
        if (panel.checker) for (let y = 0; y < boxHeight; y += 16) for (let x = 0; x < boxWidth; x += 16) {
          drawing.fillStyle = (Math.floor(x / 16) + Math.floor(y / 16)) % 2 ? '#e0e5dc' : '#fff';
          drawing.fillRect(left + x, top + y, Math.min(16, boxWidth - x), Math.min(16, boxHeight - y));
        }
        else { drawing.fillStyle = '#fff'; drawing.fillRect(left, top, boxWidth, boxHeight); }
        const image = new Image(); image.src = panel.image; await image.decode();
        const scale = Math.min(boxWidth / image.naturalWidth, boxHeight / image.naturalHeight);
        const w = image.naturalWidth * scale, h = image.naturalHeight * scale;
        drawing.drawImage(image, left + (boxWidth - w) / 2, top + (boxHeight - h) / 2, w, h);
      }
      drawing.font = '13px Arial'; drawing.fillStyle = '#5b675d';
      drawing.fillText('REUSED_REAL_DASHSCOPE_RESULT — no new paid generation request made by this verification script', canvas.width / 2, height - 20);
      return canvas.toDataURL('image/png');
    }, { original, generated, cutout });
    await writeFile(path.join(output, 'original-generated-transparent-comparison.png'), Buffer.from(comparison.split(',')[1], 'base64'));
  });

  if (originalBytes) await check('UI reuses the real generated result, requires confirmation and saves its original photograph', async () => {
    await page.evaluate(async ({ url }) => (await import('./src/flatlay.js')).setFlatlayConfig({ url, token: '' }), { url: replayBase });
    await action('add-item').click();
    await page.locator('#item-form [name="name"]').fill('真实百炼结果复用验证');
    await page.locator('#item-form [name="category"]').selectOption(category);
    await page.locator('#item-form [name="targetDescription"]').fill(description);
    await page.locator('#item-photo').setInputFiles({ name: path.basename(originalPath), mimeType: originalMime, buffer: originalBytes });
    await page.waitForFunction(() => document.querySelector('#item-form')?.dataset.photoBusy !== 'true'
      && document.querySelector('#photo-preview img')?.src.startsWith('data:image/'));
    const uploadedOriginal = await page.locator('#photo-preview img').getAttribute('src');
    await action('ai-flatlay').click(); await action('confirm-flatlay').waitFor({ timeout: 240_000 });
    assert.equal(replayRequests.length, 1); assert.equal(replayRequests[0].image, uploadedOriginal); assert.equal(replayRequests[0].category, category);
    assert.equal(await page.locator('#item-form button[type="submit"]').isDisabled(), true);
    const preview = await page.locator('#photo-preview img').getAttribute('src');
    assert.equal(preview, cutout, 'The UI should transparently cut out the same reused generation');
    await page.screenshot({ path: path.join(output, 'reused-real-ui-pending.png'), fullPage: true });
    await action('confirm-flatlay').click(); await page.locator('#item-form button[type="submit"]').click();
    await page.waitForFunction(() => !document.querySelector('dialog'));
    const item = await page.evaluate(async () => (await (await import('./src/data.js')).loadState()).items.find(value => value.name === '真实百炼结果复用验证'));
    assert.equal(item.imageKind, 'flatlay'); assert.equal(item.originalImage, uploadedOriginal); assert.equal(item.image, cutout);
    const classification = await page.evaluate(async item => {
      const module = await import('./src/model.js');
      const state = await (await import('./src/data.js')).loadState();
      return { eligible: module.isProcessedPhoto(item), status: module.outfitSuggestionStatus(state.items), suggestedIds: module.suggestOutfit(state.items).map(item => item.id) };
    }, item);
    assert.equal(classification.eligible, true);
    if (category === '连衣裙') assert.ok(classification.suggestedIds.includes(item.id));
    else { assert.equal(classification.status.code, 'incomplete'); assert.deepEqual(classification.suggestedIds, []); }
    ui = { skipped: false, imageKind: item.imageKind, savedOriginalPreserved: item.originalImage === uploadedOriginal, eligibleForAutomaticOutfit: classification.eligible,
      automaticOutfitStatus: classification.status.code, actualCompanionRequired: category !== '连衣裙', replayCalls: 1, newProviderCalls: 0 };
    await page.screenshot({ path: path.join(output, 'reused-real-ui-saved.png'), fullPage: true });
  });

  await check('all network use stayed on the local static server or the intercepted replay endpoint', async () => {
    assert.deepEqual(errors, []); assert.deepEqual(forbiddenRequests, []);
  });
} catch (error) {
  console.error(error.stack); process.exitCode = 1;
  await page.screenshot({ path: path.join(output, 'reuse-verification-failure.png'), fullPage: true }).catch(() => {});
} finally {
  await writeFile(path.join(output, 'reuse-verification.json'), JSON.stringify({
    verification: 'REUSED_REAL_DASHSCOPE_RESULT',
    scope: 'Real previously generated DashScope PNG; actual local ONNX background removal; intercepted browser reuse of the same generation. No paid provider request was made by this script.',
    limitation: 'Alpha checks establish transparency and preserved foreground, not complete garment fidelity or absence of human anatomy. Those require visual review of the actual artifacts.',
    generatedPath, originalPath: originalBytes ? originalPath : null, category, model, newProviderCalls: 0, checks, alpha, progress, resources, ui, errors, forbiddenRequests,
  }, null, 2));
  await context.close(); await browser.close();
  console.log(`Reused real-result verification: ${path.join(output, 'reuse-verification.json')}`);
}
